            [
                'key' => 'investing',
                'title' => 'Investir à Paris',
                'items' => [
                    ['question' => "Pourquoi investir dans l'immobilier de prestige à Paris ?", 'answer' => "Paris reste l'un des marchés les plus recherchés au monde : offre limitée dans les arrondissements centraux, demande internationale constante et forte résistance des prix dans les segments haut de gamme, ce qui en fait une valeur de long terme."],
                    ['question' => 'Quels quartiers privilégier pour un investissement patrimonial ?', 'answer' => "Le Marais, Saint-Germain-des-Prés, le Triangle d'Or, la Plaine Monceau et l'ouest parisien concentrent les biens les plus liquides. Nos conseillers vous orientent selon votre objectif : rendement locatif, résidence secondaire ou transmission."],
                    ['question' => "Accompagnez-vous la gestion du bien après l'achat ?", 'answer' => "Oui. Nous mettons en relation nos clients avec des partenaires de confiance pour la gestion locative, les travaux et la conciergerie, afin qu'un investissement depuis l'étranger reste simple à suivre."],
                    ['question' => 'Quel rendement locatif attendre à Paris ?', 'answer' => "Dans le prestige, le rendement brut se situe généralement entre 2 et 3,5 % : l'investissement se justifie d'abord par la sécurité du capital et la valorisation à long terme, plus que par le revenu immédiat."],
                    ['question' => 'Peut-on louer un bien en meublé de courte durée à Paris ?', 'answer' => "La location touristique d'une résidence secondaire est très encadrée à Paris et nécessite en général une autorisation de changement d'usage avec compensation. La location meublée longue durée ou le bail mobilité restent des options plus simples."],
                    ['question' => 'Faut-il acheter en nom propre ou via une société ?', 'answer' => "L'achat en nom propre est le plus simple ; la SCI facilite la détention à plusieurs et la transmission. Le bon choix dépend de votre situation fiscale et familiale : nous vous orientons vers un notaire ou un avocat fiscaliste avant l'acquisition."],
                    ['question' => 'Quelles taxes annuelles pour un propriétaire à Paris ?', 'answer' => "La taxe foncière, la taxe d'habitation sur les résidences secondaires, et au-delà de 1,3 million d'euros de patrimoine immobilier net, l'impôt sur la fortune immobilière. Nous estimons ces charges avec vous avant tout achat."],
                    ['question' => 'Comment évolue le marché parisien du prestige ?', 'answer' => "Après une correction modérée en 2023-2024, les biens d'exception bien situés ont retrouvé une demande soutenue, portée par les acquéreurs internationaux. Nous publions chaque semaine notre lecture du marché dans [la newsletter](newsletter)."],
                    ['question' => 'Peut-on acheter un immeuble entier ou un hôtel particulier ?', 'answer' => 'Oui. Ces biens rares circulent le plus souvent off-market. Nous accompagnons familles, family offices et investisseurs dans leur recherche, leur analyse et la négociation.'],
                    ['question' => "Combien de temps faut-il conserver un bien pour rentabiliser l'achat ?", 'answer' => "Compte tenu des frais d'acquisition, comptez au minimum cinq à sept ans. Sur le prestige parisien, l'horizon patrimonial se situe plutôt à dix ans et au-delà."],
